sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {

 var jan = api.data.record_1.form.fields.u_january.displayValue;
 var feb = api.data.record_1.form.fields.u_february.displayValue;
 var mar = api.data.record_1.form.fields.u_march.displayValue;
 var apr = api.data.record_1.form.fields.u_april.displayValue;
 var may = api.data.record_1.form.fields.u_may.displayValue;
 var jun = api.data.record_1.form.fields.u_june.displayValue;
 var jul = api.data.record_1.form.fields.u_july.displayValue;
 var aug = api.data.record_1.form.fields.u_august.displayValue;
 var sept = api.data.record_1.form.fields.u_september.displayValue;
 var oct = api.data.record_1.form.fields.u_october.displayValue;
 var nov = api.data.record_1.form.fields.u_november.displayValue;
 var dec = api.data.record_1.form.fields.u_december.displayValue;
 var year = api.data.record_1.form.fields.u_year.displayValue;
 var totalB = api.data.record_1.form.fields.u_total_budget.displayValue;

 var months = [jan,feb,mar,apr,may,jun,jul,aug,sept,oct,nov,dec];
 var choices =['january','february','march', 'april','may','june', 'july','august', 'september','october','november','december'];
 console.log('Executed : '+months+' -- '+year+' -- '+totalB);
 api.data.create_a_record_1.execute({
    totalB:totalB,
    year:year,
    months:months,
    number:api.state.wbsNumber
 });
console.log('Executed..');
console.log('WBS '+api.state.wbsNumber);
}
